import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    private static final Instant NOW = Instant.parse("2026-10-31T12:00:00Z");

    private final OrderRepository orders = new OrderRepository();
    private final OrderService service =
            new OrderService(orders, Clock.fixed(NOW, ZoneOffset.UTC));

    @Test
    void cancelsOnlyPlacedOrdersOlderThanThirtyDays() {
        save("old-placed", "PLACED", NOW.minusSeconds(31L * 24 * 3600));
        save("boundary-placed", "PLACED", NOW.minusSeconds(30L * 24 * 3600));
        save("recent-placed", "PLACED", NOW.minusSeconds(29L * 24 * 3600));
        save("old-confirmed", "CONFIRMED", NOW.minusSeconds(60L * 24 * 3600));
        save("old-cancelled", "CANCELLED", NOW.minusSeconds(60L * 24 * 3600));

        int cancelled = service.expireStale();

        assertEquals(1, cancelled);
        assertEquals("CANCELLED", orders.get("old-placed").status());
        assertEquals("PLACED", orders.get("boundary-placed").status());
        assertEquals("PLACED", orders.get("recent-placed").status());
        assertEquals("CONFIRMED", orders.get("old-confirmed").status());
        assertEquals("CANCELLED", orders.get("old-cancelled").status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        save("recent", "PLACED", NOW.minusSeconds(60));

        assertEquals(0, service.expireStale());
        assertEquals("PLACED", orders.get("recent").status());
    }

    @Test
    void secondRunCancelsNothingMore() {
        save("old", "PLACED", NOW.minusSeconds(40L * 24 * 3600));

        assertEquals(1, service.expireStale());
        assertEquals(0, service.expireStale());
    }

    private void save(String id, String status, Instant placedAt) {
        Order order = new Order(id, "c-1", Money.pln(1000), placedAt);
        order.changeStatus(status);
        orders.save(order);
    }
}
